/* @autogenerated */
package net.civeira.phylax.feature.observe.anomaly;

import java.time.DayOfWeek;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import net.civeira.phylax.feature.observe.metric.Histogram;
import net.civeira.phylax.feature.observe.metric.MetricDeriver;
import net.civeira.phylax.feature.observe.metric.MetricPoint;

/**
 * What is usual for each source: mean and deviation of its requests per minute, error rate and p95
 * for each slot of the week (working day or weekend × hour of the day, UTC), from the hourly points
 * of the last weeks. Anomaly detection compares the present with the slot of now.
 */
public final class Baselines {

  public static final String RPM = "rpm";
  public static final String ERRORS = "errorRate";
  public static final String P95 = "p95";

  /** Mean and deviation of a metric in a slot, from {@code samples} hours. */
  public record Stat(double mean, double std, int samples) {}

  /** Per source → slot → metric → statistic. */
  private final Map<String, Map<Integer, Map<String, Stat>>> stats;

  private Baselines(final Map<String, Map<Integer, Map<String, Stat>>> stats) {
    this.stats = stats;
  }

  public static Baselines empty() {
    return new Baselines(Map.of());
  }

  /** Slot of a moment: 0-23 working days, 24-47 weekend. */
  public static int slot(final long epochMillis) {
    ZonedDateTime time = Instant.ofEpochMilli(epochMillis).atZone(ZoneOffset.UTC);
    boolean weekend =
        time.getDayOfWeek() == DayOfWeek.SATURDAY || time.getDayOfWeek() == DayOfWeek.SUNDAY;
    return (weekend ? 24 : 0) + time.getHour();
  }

  public Stat stat(final String source, final int slot, final String metric) {
    return stats.getOrDefault(source, Map.of()).getOrDefault(slot, Map.of()).get(metric);
  }

  /** Builds the baselines from hourly points (requests of the sources, not probes nor edges). */
  public static Baselines of(final List<MetricPoint> points) {
    // source → hour → aggregate
    Map<String, Map<Long, double[]>> hours = new HashMap<>();
    Map<String, Map<Long, Histogram>> latency = new HashMap<>();
    for (MetricPoint point : points) {
      if (MetricDeriver.special(point.method())) {
        continue;
      }
      long hour = point.ts() / MetricDeriver.HOUR * MetricDeriver.HOUR;
      double[] acc = hours.computeIfAbsent(point.src(), s -> new HashMap<>()).computeIfAbsent(hour,
          h -> new double[2]);
      acc[0] += point.count();
      acc[1] += point.errors();
      latency.computeIfAbsent(point.src(), s -> new HashMap<>())
          .computeIfAbsent(hour, h -> new Histogram()).merge(point.buckets());
    }
    Map<String, Map<Integer, Map<String, Stat>>> result = new HashMap<>();
    hours.forEach((source, byHour) -> {
      Map<Integer, Map<String, double[]>> sums = new HashMap<>();
      byHour.forEach((hour, acc) -> {
        int slot = slot(hour);
        Map<String, double[]> metric = sums.computeIfAbsent(slot, s -> new HashMap<>());
        add(metric, RPM, acc[0] / 60.0);
        if (acc[0] > 0) {
          add(metric, ERRORS, 100.0 * acc[1] / acc[0]);
          Double p95 = latency.get(source).get(hour).percentile(0.95);
          if (null != p95) {
            add(metric, P95, p95);
          }
        }
      });
      Map<Integer, Map<String, Stat>> bySlot = new HashMap<>();
      sums.forEach((slot, metrics) -> {
        Map<String, Stat> computed = new HashMap<>();
        metrics.forEach((name, s) -> {
          double mean = s[1] / s[0];
          double variance = Math.max(0, s[2] / s[0] - mean * mean);
          computed.put(name, new Stat(mean, Math.sqrt(variance), (int) s[0]));
        });
        bySlot.put(slot, computed);
      });
      result.put(source, bySlot);
    });
    return new Baselines(result);
  }

  /** Running sums: count, sum, sum of squares. */
  private static void add(final Map<String, double[]> metrics, final String name,
      final double value) {
    double[] s = metrics.computeIfAbsent(name, n -> new double[3]);
    s[0]++;
    s[1] += value;
    s[2] += value * value;
  }
}
